<template>
  <el-dialog :title="business ? '业务退款详情 · '+label(row&&row.platform&&row.platform.dispute_type) : '平台退款详情'" :visible.sync="visible" width="92%" append-to-body :close-on-click-modal="false">
    <div v-loading="loading" v-if="row">
      <header class="refund-identity">
        <div class="refund-identity-main"><strong>{{ business ? row.refund_sn : row.refund_id }}</strong><span class="refund-type">{{ label(platform.dispute_type) }}</span><el-tag v-if="business" size="small" :type="scenario.tone" effect="plain">{{ scenario.text }}</el-tag><el-popover placement="bottom-start" trigger="click" width="360"><dl class="related-numbers"><dt>平台退款单</dt><dd>{{ row.refund_id }}</dd><dt>平台订单</dt><dd>{{ row.platform_tid }}</dd><dt>平台子订单</dt><dd>{{ row.platform_oid }}</dd><dt v-if="business">OMS 订单</dt><dd v-if="business">{{ row.order_sn }}</dd><dt>平台状态</dt><dd>{{ label(platform.platform_status) }}</dd></dl><el-button slot="reference" size="small" type="text">关联单号</el-button></el-popover></div>
        <div class="refund-amount"><span class="hint">{{ business && row.approved_version ? '已采用申请金额' : '本次申请金额' }}</span><strong>{{ money(business ? row.refund_fee : platform.refund_fee) }}</strong></div>
        <div v-if="business" class="refund-status-line"><strong>{{ processingSummary }}</strong><span class="hint">审核：{{ label(row.review_state) }}</span><el-tooltip content="实际资金结果来自平台同步；货物处理进度独立跟踪。" placement="top"><i class="el-icon-info hint" aria-label="资金和货物状态说明" tabindex="0"/></el-tooltip></div>
        <div v-else class="refund-status-line">平台状态：{{ platform.platform_status === 'SUCCESS' ? '退款成功' : label(platform.platform_status) }}</div>
      </header>
      <template v-if="business">
        <el-tabs v-model="detailTab">
          <el-tab-pane label="本次处理" name="current">
            <section v-if="currentTask" class="refund-current-task"><div><strong>{{ currentTask.title }}</strong><p>{{ currentTask.message }}</p></div><el-button size="small" type="primary" plain @click="openTask">{{ currentTask.action }}</el-button></section>
            <el-alert v-if="amountChanged" title="平台申请金额已变化，请核对已采用方案与最新申请" :description="'已采用 ' + money(row.refund_fee) + '；平台最新 ' + money(platform.refund_fee)" type="warning" :closable="false" show-icon/>
            <refund-application-goods :refund="row" @open-goods="scrollToGoods"/>
            <order-gifts v-if="visible && row.order_id" ref="gifts" :key="row.id" :order-id="row.order_id" :refund-id="row.id" @loaded="giftReport=$event" @changed="changed('gifts')" @open-goods="openGiftGoods"/>

          </el-tab-pane>
          <el-tab-pane label="退回与包裹" name="goods" lazy>      <section v-if="business&&(row.parcel_issues||[]).length" class="parcel-issue-tasks"><article v-for="issue in row.parcel_issues" :key="issue.plan_id" class="parcel-issue-task"><el-alert :title="issue.title" :description="issue.reason" type="warning" show-icon :closable="false"/><p><b>本退款：</b>计划退回 {{ issue.quantity }} 件 · 实收 {{ issue.accepted_quantity }} 件 · 入账 {{ issue.posted_quantity }} 件 · {{ issue.has_document?'已有THK，请核对原单':'未生成THK，尚未加入目标包裹' }}</p><p v-if="issue.target_parcel_sn"><b>目标包裹：</b>{{ issue.target_parcel_sn }}<br><span class="hint">{{ issue.carrier_code }} · {{ issue.waybill }} · 退回仓 {{ issue.store_code }}</span></p><p><b>下一步：</b>{{ issue.next_action }}</p><el-button v-hasPermi="['order:refund:goods']" type="primary" size="small" @click="openIssue(issue.plan_id)">核对合包归属</el-button><el-button size="small" @click="openIssue(issue.plan_id)">查看目标包裹与回传</el-button><p class="hint">重新检查不会解除实收后的自动追加限制；原包裹实收不能直接认定属于本退款。</p></article></section>
      <section v-if="business&&(row.parcel_followups||[]).length"><el-alert v-for="task in row.parcel_followups" :key="task.plan_id" :title="task.title" :description="task.next_action" type="info" show-icon :closable="false"/><el-button size="small" type="primary" @click="scrollToGoods">{{ row.parcel_followups.some(t=>t.manual_dispatch)?'去下发补充THK':'去登记真实寄回物流' }}</el-button></section>
      <el-alert v-if="row.problem_message || platform.source_error || platform.conversion_error" :title="row.problem_message || platform.source_error || platform.conversion_error" type="warning" :closable="false" show-icon />
<refund-goods v-if="visible" ref="goods" :key="row.id" :refund="row" :active="detailTab === 'goods'" @changed="changed('goods')"/></el-tab-pane>
          <el-tab-pane label="审核与来源" name="approval" lazy>        <el-alert :title="(row.capability || {}).message || '按审核方案分别处理资金与货物'" type="info" :closable="false" show-icon />
        <h4>本次采用方案</h4><el-descriptions border :column="2" size="small"><el-descriptions-item label="审核人 / 时间">{{ row.review_by || '—' }} / {{ row.reviewed_at || '—' }}</el-descriptions-item><el-descriptions-item label="采用来源版本">{{ row.approved_version || '—' }}</el-descriptions-item><el-descriptions-item label="审核依据">{{ row.review_reason || '—' }}</el-descriptions-item><el-descriptions-item label="协商凭证">{{ row.review_evidence || '—' }}</el-descriptions-item><el-descriptions-item v-if="row.cancel_quantity" label="取消方案">商品明细 #{{ row.cancel_line_id }} · {{ row.cancel_quantity }} 件；已执行 {{ row.cancelled_quantity }} 件</el-descriptions-item></el-descriptions>
        <el-button v-hasPermi="['order:refund:review']" size="small" type="primary" style="margin-top:16px" @click="prepareReview">{{ row.approved_version ? '核对并重审方案' : '审核退款方案' }}</el-button>
<el-collapse class="platform-evidence"><el-collapse-item title="平台来源资料与同步版本" name="platform">      <el-descriptions :column="3" border size="small" style="margin:20px 0"><el-descriptions-item label="来源资料">{{ label(platform.source_state) }}</el-descriptions-item><el-descriptions-item label="平台类型">{{ label(platform.dispute_type) }} · {{ label(platform.source_phase) }}</el-descriptions-item><el-descriptions-item label="平台退款版本">{{ platform.refund_version || '未提供；资金操作前需重新获取' }}</el-descriptions-item><el-descriptions-item label="本地来源版本">{{ platform.version }}</el-descriptions-item><el-descriptions-item label="平台修改时间">{{ platform.source_modified }}</el-descriptions-item><el-descriptions-item label="最近同步">{{ platform.last_sync }}</el-descriptions-item><el-descriptions-item label="申请原因" :span="3">{{ platform.reason || '—' }}</el-descriptions-item></el-descriptions>
      <el-alert v-if="platform.return_logistics&&platform.return_logistics.waybill" type="info" :closable="false" :title="`平台寄回物流：${platform.return_logistics.carrier_name||'快递待核对'} · ${platform.return_logistics.waybill}`" description="这是平台来源事实，不会覆盖已下发仓库单或自动增加库存；请在退回包裹中核对关联。"/>
</el-collapse-item></el-collapse>
        <el-collapse><el-collapse-item title="原订单商品与实际发货来源（追溯）" name="source"><h4>原子订单的实际商品</h4><p class="hint">同一 SKU 在不同换货轮次中分别保留商品明细，支持追溯 A → B → A。</p><el-table :data="row.lines"><el-table-column prop="id" label="商品明细 ID" width="120" /><el-table-column label="商品 / SKU" min-width="240"><template slot-scope="s">{{ s.row.goods_name }}<div class="hint">{{ s.row.sku_sn }}</div></template></el-table-column><el-table-column prop="business_type" label="归属" width="100" /><el-table-column prop="exchange_id" label="换货 ID" width="100" /><el-table-column prop="quantity" label="商品数量" width="110" /><el-table-column prop="cancelled_quantity" label="已取消" width="100" /><el-table-column prop="stock_reference" label="库存业务来源" min-width="190" /></el-table>
        <h4>实际发货来源</h4><p class="hint">发货单、发货明细与库存来源共同区分实际发出的商品；平台申请数量不直接作为取消或退回数量。</p><el-table :data="row.shipments" empty-text="尚无发货单"><el-table-column prop="shipment_sn" label="发货单" min-width="300" /><el-table-column prop="shipment_line_id" label="发货明细 ID" width="120" /><el-table-column prop="sku_sn" label="SKU" min-width="180" /><el-table-column prop="exchange_id" label="换货 ID" width="100" /><el-table-column label="计划 / 已出库" width="150"><template slot-scope="s">{{ s.row.quantity }} / {{ s.row.shipped_quantity }} 件</template></el-table-column><el-table-column prop="store_code" label="虚拟仓" min-width="140" /></el-table>
        </el-collapse-item></el-collapse>
</el-tab-pane>
          <el-tab-pane label="处理记录" name="events" lazy><h4>处理记录</h4><el-table :data="row.events"><el-table-column prop="create_time" label="时间" width="180" /><el-table-column prop="actor" label="操作人" width="110" /><el-table-column prop="message" label="记录" min-width="500" /></el-table>
</el-tab-pane>
        </el-tabs>
      </template>
      <template v-else>
      <el-alert v-if="row.problem_message || platform.source_error || platform.conversion_error" :title="row.problem_message || platform.source_error || platform.conversion_error" type="warning" :closable="false" show-icon />
      <el-descriptions :column="3" border size="small" style="margin:20px 0"><el-descriptions-item label="来源资料">{{ label(platform.source_state) }}</el-descriptions-item><el-descriptions-item label="平台类型">{{ label(platform.dispute_type) }} · {{ label(platform.source_phase) }}</el-descriptions-item><el-descriptions-item label="平台退款版本">{{ platform.refund_version || '未提供；资金操作前需重新获取' }}</el-descriptions-item><el-descriptions-item label="本地来源版本">{{ platform.version }}</el-descriptions-item><el-descriptions-item label="平台修改时间">{{ platform.source_modified }}</el-descriptions-item><el-descriptions-item label="最近同步">{{ platform.last_sync }}</el-descriptions-item><el-descriptions-item label="申请原因" :span="3">{{ platform.reason || '—' }}</el-descriptions-item></el-descriptions>
      <el-alert v-if="platform.return_logistics&&platform.return_logistics.waybill" type="info" :closable="false" :title="`平台寄回物流：${platform.return_logistics.carrier_name||'快递待核对'} · ${platform.return_logistics.waybill}`" description="这是平台来源事实，不会覆盖已下发仓库单或自动增加库存；请在退回包裹中核对关联。"/>
<p v-if="row.message">后台转单 <message-progress :message="row.message" type="REFUND_CONVERT"/></p><el-button v-if="!row.business_refund_id" v-hasPermi="['order:refund:convert']" type="primary" size="small" @click="convert">{{ row.conversion_state==='FAILED' ? '重试转业务退款单' : '转业务退款单' }}</el-button><el-button v-else type="primary" size="small" @click="goBusiness">查看业务退款单</el-button><h4>推送原文与来源版本</h4><p class="hint">仅代表平台事实；转单、审核、平台退款、库存入账分别留痕。</p><el-table :data="row.snapshots"><el-table-column prop="create_time" label="收到时间" width="180" /><el-table-column prop="source_modified" label="平台修改时间" width="180" /><el-table-column prop="jdp_modified" label="推送库更新时间" width="180" /><el-table-column label="识别结果" width="150"><template slot-scope="s">{{ label(s.row.outcome) }}</template></el-table-column><el-table-column label="操作"><template slot-scope="s"><el-button type="text" @click="snapshot(s.row)">查看本次原文</el-button></template></el-table-column></el-table></template>
    </div>
    <div slot="footer" class="refund-footer"><span v-if="business && currentTask" class="footer-task">{{ currentTask.title }}</span><div class="footer-buttons"><el-popover v-if="business && row" placement="top-end" trigger="click" width="180"><el-button v-hasPermi="['order:refund:config']" type="text" @click="goReturnRules">本店铺退货规则</el-button><el-button slot="reference" size="small">更多</el-button></el-popover><el-button size="small" :loading="loading" :disabled="!row" @click="reload()">刷新详情</el-button><el-button size="small" @click="visible=false">关闭</el-button><el-button v-if="business && currentTask" size="small" type="primary" :disabled="loading" @click="openTask">{{ currentTask.action }}</el-button></div></div>
    <el-dialog :title="'审核'+label(platform&&platform.dispute_type)+'方案'" :visible.sync="reviewVisible" width="760px" append-to-body :close-on-click-modal="false"><el-alert title="审核只保存业务方案。金额来自平台申请，不会执行平台付款；货物处理也不会凭审核自动扣减或增加库存。" type="info" :closable="false" /><el-form label-width="125px" style="margin-top:20px"><el-form-item label="退款用途" required><el-select v-model="form.purpose"><el-option v-for="v in purposes" :key="v" :value="v" :label="label(v)" /></el-select></el-form-item><el-form-item label="货物处理" required><el-select v-model="form.goods_action" @change="goodsChanged"><el-option v-for="v in availableGoodsActions" :key="v" :value="v" :label="label(v)" /></el-select></el-form-item><template v-if="form.goods_action==='CANCEL'"><el-form-item label="取消商品明细" required><el-select v-model="form.cancel_line_id" style="width:100%"><el-option v-for="l in row.lines" :key="l.id" :value="l.id" :label="`#${l.id} ${l.sku_sn} · ${l.goods_name}`" /></el-select></el-form-item><el-form-item label="明确取消数量" required><el-input-number v-model="form.cancel_quantity" :min="1" :precision="0" /></el-form-item></template><el-form-item label="审核依据" required><el-input v-model="form.reason" type="textarea" maxlength="500" show-word-limit /></el-form-item><el-form-item label="协商 / 证明凭证" required><el-input v-model="form.evidence" type="textarea" maxlength="1000" show-word-limit placeholder="客服记录、平台处理依据、拒收或拦截凭证" /></el-form-item><el-form-item><el-checkbox v-model="confirmed">已核对用途、货物处理及本次平台版本</el-checkbox></el-form-item></el-form><span slot="footer"><el-button @click="reviewVisible=false">取消</el-button><el-button type="primary" :loading="saving" :disabled="!confirmed" @click="review">保存审核方案</el-button></span></el-dialog>
    <el-dialog title="平台推送原文" :visible.sync="rawVisible" width="85%" append-to-body><pre class="raw">{{ raw }}</pre></el-dialog>
  </el-dialog>
</template>
<script>
import * as api from '@/api/order/refund'
import RefundGoods from './RefundGoods'
import OrderGifts from './OrderGifts'
import MessageProgress from '@/views/oms/messaging/MessageProgress'
import RefundApplicationGoods from './RefundApplicationGoods'
import { refundGiftRows, refundCurrentTask, refundGoodsNextAction, refundScenario } from './refundDetailPresentation'
import { money, amount } from './orderAmounts'
import { label, purposes, goodsActions } from './refundLabels'
export default { name: 'RefundDetail', components:{OrderGifts,RefundGoods,RefundApplicationGoods,MessageProgress}, props: { business: Boolean }, data: () => ({ visible: false, loading: false, saving: false, row: null, reviewVisible: false, form: {}, confirmed: false, purposes, goodsActions, rawVisible: false, raw: '', detailTab: 'current', giftReport: null, sequence: 0 }), beforeDestroy() { this.sequence++ }, computed: {
  scenario() { return refundScenario(this.row || {}) },
  amountChanged() { return !!(this.row && this.row.approved_version && this.platform && this.row.refund_fee != null && this.platform.refund_fee != null && amount(this.row.refund_fee) !== amount(this.platform.refund_fee)) },
  currentGiftRows() { return refundGiftRows(((this.giftReport || {}).lines || []), (this.row || {}).id) },
  processingSummary() {
    const row = this.row || {}, parts = [row.funds_state === 'SUCCESS' ? '平台已退款' : '平台资金：' + label(row.funds_state), '购买商品：' + label(row.goods_state)]
    if (this.currentGiftRows.some(line => line.needs_action)) parts.push('关联赠品待处理')
    return parts.join(' · ')
  },
  currentTask() { return refundCurrentTask(this.row || {}, this.currentGiftRows, this.goodsNextAction) }, availableGoodsActions(){return this.platform&&this.platform.dispute_type==='REFUND_AND_RETURN'?['RETURN','REFUSAL','INTERCEPT']:this.goodsActions},goodsNextAction(){return refundGoodsNextAction(this.row || {})},platform() { return this.business ? (this.row&&this.row.platform) : this.row } }, methods: {
  openTask() { if (!this.currentTask) return; if (this.currentTask.gifts) return this.openGiftGoods(); this.detailTab = this.currentTask.tab },
  openGiftGoods() { this.detailTab = 'goods'; this.$nextTick(() => { if (this.$refs.goods) this.$refs.goods.planScope = 'gift' }) },
  openIssue(id) { this.detailTab = 'goods'; this.$nextTick(() => { if (this.$refs.goods) this.$refs.goods.openIssue(id) }) },
  goReturnRules(){this.visible=false;this.$router.push({path:'/oms-order/afterSaleRules/returns',query:{channelId:this.row.channel_id,refundId:this.row.id}})},
  startParcelWaive(plan){if(this.$refs.goods)this.$refs.goods.startParcelWaive(plan)},
  scrollToGoods() { this.detailTab = 'goods'; this.$nextTick(() => { if (this.$refs.goods) { this.$refs.goods.planScope = 'purchase'; this.$refs.goods.$el.scrollIntoView({ block: 'start', behavior: 'smooth' }) } }) },
  async changed(source) { await this.reload(source); this.$emit('changed') }, label, money,
  async reload(source) { if (this.row) return this.open(this.row.id, false, false, true, source) },
  async open(id, focusIssue = false, focusParcel = false, preserve = false, source = '') {
    const sequence = ++this.sequence
    const same = this.row && String(this.row.id) === String(id)
    this.visible = true
    this.loading = true
    if (!same) { this.row = null; this.giftReport = null }
    if (!preserve || !same) this.detailTab = focusIssue || focusParcel ? 'goods' : 'current'
    try {
      const row = (await api.refundDetail(this.business, id)).data
      if (sequence !== this.sequence) return
      this.row = row
      await this.$nextTick()
      if (preserve && source !== 'gifts' && this.$refs.gifts) await this.$refs.gifts.load()
      if (focusIssue && (row.parcel_issues || []).length) this.openIssue(row.parcel_issues[0].plan_id)
      if (focusParcel && this.$refs.goods) this.$refs.goods.openParcels()
    } finally { if (sequence === this.sequence) this.loading = false }
  },
  async convert() { const r = (await api.convertRefund(this.row.id)).data; if (r.state === 'SUCCESS') this.$message.success('已转业务退款单'); else if(r.state==='PENDING')this.$message.success(r.message);else this.$message.warning(r.message || label(r.state)); await this.reload(); this.$emit('changed') },
  goBusiness() { this.visible = false; this.$router.push({ path: '/oms-order/businessRefunds', query: { id: this.row.business_refund_id } }) },
  prepareReview() { this.form = { control_version: this.row.control_version, platform_version: this.platform.version, purpose: this.row.purpose === 'UNKNOWN' ? '' : this.row.purpose, goods_action: this.row.goods_action === 'UNKNOWN' ? (this.platform.dispute_type==='REFUND_AND_RETURN'?'RETURN':'') : this.row.goods_action, reason: '', evidence: '', cancel_line_id: this.row.cancel_line_id || 0, cancel_quantity: this.row.cancel_quantity || 0 }; this.confirmed = false; this.reviewVisible = true },
  goodsChanged() { this.form.cancel_line_id = 0; this.form.cancel_quantity = this.form.goods_action === 'CANCEL' ? 1 : 0 },
  async review() { this.saving = true; try { await api.refundReview(this.row.id, this.form); this.$message.success('审核方案已保存；可分别核对资金和货物处理'); this.reviewVisible = false; await this.reload(); this.$emit('changed') } finally { this.saving = false } },
  async snapshot(s) { const r = (await api.refundSnapshot(this.row.id, s.id)).data; try { this.raw = JSON.stringify(JSON.parse(r.payload), null, 2) } catch (_) { this.raw = r.payload } this.rawVisible = true }
} }
</script>
